using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using OCRS.Data; using OCRS.Models;
namespace OCRS.Areas.Admin.Controllers;
[Area("Admin"),Authorize(Roles="Admin")] public class CategoriesController(ApplicationDbContext db):Controller { public async Task<IActionResult> Index(string? q,bool? active){var x=db.Categories.AsQueryable();if(!string.IsNullOrWhiteSpace(q))x=x.Where(c=>c.CategoryName.Contains(q));if(active.HasValue)x=x.Where(c=>c.IsActive==active);return View(await x.OrderBy(c=>c.CategoryName).ToListAsync());} public IActionResult Create()=>View("Form",new Category()); [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Create(Category m){if(await db.Categories.AnyAsync(x=>x.CategoryName.ToLower()==m.CategoryName.Trim().ToLower()))ModelState.AddModelError(nameof(m.CategoryName),"Tên danh mục đã tồn tại.");if(!ModelState.IsValid)return View("Form",m);m.CategoryName=m.CategoryName.Trim();db.Add(m);await db.SaveChangesAsync();TempData["Success"]="Đã thêm danh mục.";return RedirectToAction(nameof(Index));} public async Task<IActionResult> Edit(int id){var m=await db.Categories.FindAsync(id);return m==null?NotFound():View("Form",m);} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Edit(int id,Category m){if(id!=m.CategoryId)return BadRequest();if(await db.Categories.AnyAsync(x=>x.CategoryId!=id&&x.CategoryName.ToLower()==m.CategoryName.Trim().ToLower()))ModelState.AddModelError(nameof(m.CategoryName),"Tên danh mục đã tồn tại.");if(!ModelState.IsValid)return View("Form",m);db.Update(m);await db.SaveChangesAsync();TempData["Success"]="Đã cập nhật danh mục.";return RedirectToAction(nameof(Index));} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Toggle(int id){var m=await db.Categories.FindAsync(id);if(m!=null){m.IsActive=!m.IsActive;await db.SaveChangesAsync();}return RedirectToAction(nameof(Index));} }
